class DinnerPlates {
  private final int capacity;
  private final java.util.List<java.util.Deque<Integer>> stacks = new java.util.ArrayList<>();
  private final java.util.TreeSet<Integer> available = new java.util.TreeSet<>();

  public DinnerPlates(int capacity) {
    this.capacity = capacity;
  }

  public void push(int val) {
    int index = available.isEmpty() ? stacks.size() : available.first();
    if (index == stacks.size()) stacks.add(new java.util.ArrayDeque<>());
    stacks.get(index).push(val);
    if (stacks.get(index).size() == capacity) available.remove(index);
    else available.add(index);
  }

  public int pop() {
    while (!stacks.isEmpty() && stacks.get(stacks.size() - 1).isEmpty())
      stacks.remove(stacks.size() - 1);
    if (stacks.isEmpty()) return -1;
    int index = stacks.size() - 1, value = stacks.get(index).pop();
    available.add(index);
    while (!stacks.isEmpty() && stacks.get(stacks.size() - 1).isEmpty())
      stacks.remove(stacks.size() - 1);
    while (!available.isEmpty() && available.last() >= stacks.size())
      available.remove(available.last());
    return value;
  }

  public int popAtStack(int index) {
    if (index < 0 || index >= stacks.size() || stacks.get(index).isEmpty()) return -1;
    int value = stacks.get(index).pop();
    available.add(index);
    return value;
  }
}
